import React, { useState } from "react";
import DataTable from "react-data-table-component";
import FetchData from "../FetchFunction";
import CreateIncidentModal from "../modals/post/CreateIncidentModal";
import httpClient from "../../../httpClient";
import Swal from "sweetalert2";
import EditCurrentUserIncident from "../modals/put/EditCurrentUserIncidents";
import { useTranslation } from "react-i18next";
import { getShortReadableDate } from "../manage_data/functions";

function ReportIncident() {
  const { t } = useTranslation();
  const [refreshIncidents, setRefreshIncidents] = useState(0);
  const [activeView, setActiveView] = useState("create");
  const [searchTerm, setSearchTerm] = useState("");
  const { data: allUserIncidents, error, loading } = FetchData("/api/user/incidents", refreshIncidents);
  let timestamp = Date.now();

  const handleDeleteIncident = async (id) => {
    const confirmDialogue = await Swal.fire({
      title: "Are you sure?",
      text: "Do you want to continue deleting this incident?",
      icon: "warning",
      showCancelButton: true,
      confirmButtonText: "Yes, delete it!",
      cancelButtonText: "Cancel",
    });
    if (!confirmDialogue.isConfirmed) return;
    try {
      document.body.style.cursor = "wait";
      await httpClient.delete("/api/user/incidents", { params: { req_incident_id: id } });
      setRefreshIncidents((prev) => !prev);
      Swal.fire("Deleted!", "The Incident Report has been deleted.", "success");
    } catch (error) {
      console.error(error);
      Swal.fire("Error!", `${error.response.data.message}`, "error");
    } finally {
      document.body.style.cursor = "default";
    }
  };

  // Define columns for the DataTable
  const columns = [
    {
      name: "Incident ID",
      selector: (row) => row.incident_id,
      sortable: true,
    },
    {
      name: "Description",
      selector: (row) => row.description,
      sortable: true,
    },
    {
      name: "Status",
      selector: (row) => row.status,
      sortable: true,
    },
    {
      name: "Location",
      selector: (row) => row.location,
      sortable: true,
    },
    {
      name: "Photo",
      cell: (row) => {
        return row.photo_path ? (
          <a
            href={`https://storage.googleapis.com/pklink/${row.photo_path.replace(/\\/g, "/")}?v=${timestamp}`}
            target="_blank"
            rel="noopener noreferrer"
          >
            <img
              src={`https://storage.googleapis.com/pklink/${row.photo_path.replace(/\\/g, "/")}?v=${timestamp}`}
              alt="Incident"
              style={{ width: "100%", maxWidth: "300px", borderRadius: "10px" }}
            />
          </a>
        ) : (
          <p>No Image</p>
        );
      },
    },
    {
      name: "Date Created",
      selector: (row) => getShortReadableDate(row.date_created),
      sortable: true,
    },
    {
      name: "Actions",
      cell: (row) =>
        row.status === "pending" ? (
          <div className="btn-group">
            <button
              className="btn btn-danger btn-sm"
              onClick={() => handleDeleteIncident(row.incident_id)}
            >
              Cancel
            </button>
            <button
              className="btn btn-warning btn-sm"
              onClick={() => EditCurrentUserIncident(allUserIncidents, row.incident_id, setRefreshIncidents)}
            >
              Edit
            </button>
          </div>
        ) : null,
    },
  ];

  // Filter incidents based on searchTerm (case-insensitive)
  const filteredIncidents = allUserIncidents
    ? allUserIncidents.filter((incident) => {
        const search = searchTerm.toLowerCase();
        return (
          incident.incident_id.toString().toLowerCase().includes(search) ||
          incident.description.toLowerCase().includes(search) ||
          incident.status.toLowerCase().includes(search) ||
          incident.location.toLowerCase().includes(search) ||
          new Date(incident.date_created).toLocaleString().toLowerCase().includes(search)
        );
      })
    : [];

  return (
    <div id="report-incident-con">
      <div className="flex-col">
        <div className="btn-group">
          <button
            onClick={() => setActiveView("create")}
            className={`btn ${activeView === "create" ? "btn-primary" : "btn-secondary"}`}
          >
            {t("content_panel.incident.create_incident")}
          </button>
          <button
            onClick={() => {
              setActiveView("manage");
              setRefreshIncidents((prev) => !prev);
            }}
            className={`btn ${activeView === "manage" ? "btn-primary" : "btn-secondary"}`}
          >
            {t("content_panel.incident.manage_my_incidents")}
          </button>
        </div>

        {activeView === "create" ? (
          <CreateIncidentModal />
        ) : (
          <div className="manage-incidents">
            {/* Search Input */}
            <div className="mb-4">
              <input
                type="text"
                placeholder="Search incidents..."
                className="p-2 border border-gray-300 rounded"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            {loading ? (
              <p>Loading...</p>
            ) : error ? (
              <p>Error fetching data.</p>
            ) : filteredIncidents.length === 0 ? (
              <p>No incident reports found.</p>
            ) : (
              <DataTable
                title="Incident Reports"
                columns={columns}
                data={filteredIncidents}
                pagination
                highlightOnHover
              />
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default ReportIncident;
