import React, { createContext, useState, useEffect } from 'react';

export const ThemeContext = createContext({
  colorMode: 'dark',
  setColorMode: () => {},
});

export const ThemeProvider = ({ children }) => {
  // Check localStorage for saved color mode; default to 'dark' if not found.
  const [colorMode, setColorModeState] = useState(() => {
    return localStorage.getItem('colorMode') || 'dark';
  });

  // Save the color mode whenever it changes.
  const setColorMode = (mode) => {
    setColorModeState(mode);
    localStorage.setItem('colorMode', mode);
  };

  useEffect(() => {
    // Update the elements that have specific classes
    const elements = document.querySelectorAll('.dark-gray-bg, .light-gray-bg');
    elements.forEach((el) => {
      el.classList.remove('dark-gray-bg', 'light-gray-bg');
      el.classList.add(`${colorMode}-gray-bg`);
    });
  }, [colorMode]);

  return (
    <ThemeContext.Provider value={{ colorMode, setColorMode }}>
      {children}
    </ThemeContext.Provider>
  );
};
