import Swal from "sweetalert2";

export function showPrivacyPolicy() {
    Swal.fire({
        title: "Privacy Policy",
        html: `
            <div style="text-align: left; max-height: 300px; overflow-y: auto; padding: 10px;">
                <p>Welcome! Please review our Privacy Policy:</p>
                <ul>
                    <li><strong>Data Collection:</strong> We collect personal information to improve your experience.</li>
                    <li><strong>Data Usage:</strong> Your data is used to provide and personalize our services.</li>
                    <li><strong>Data Security:</strong> We employ strong security measures to protect your information.</li>
                    <li><strong>Third-Party Sharing:</strong> We do not share your personal data with third parties without your consent.</li>
                    <li><strong>Your Rights:</strong> You have the right to access, modify, or delete some of your personal information.</li>
                </ul>
                <p>By using our services, you agree to the terms of our Privacy Policy.</p>
            </div>
        `,
        icon: "info",
        allowOutsideClick: false,
        showCancelButton: false,
        confirmButtonText: "Close"
    });
}
