import Swal from "sweetalert2";

export function showFigmaSitemap() {
  Swal.fire({
    title: "PKLINK Sitemap",
    html: `
      <div style="text-align: center;">
        <iframe
          title="Figma Sitemap"
          width="100%"
          height="450"
          style="border: 1px solid #ccc;"
          src="https://www.figma.com/embed?embed_host=share&url=https://www.figma.com/design/9chJBTaeVH3k8g1yW0XQ4z/Flat-SiteMaps-(Community)?node-id=0-1&p=f"
          allowfullscreen
        ></iframe>
      </div>
    `,
    width: 900,
    confirmButtonText: "Close",
    customClass: {
      popup: "figma-sitemap-popup"
    }
  });
}
