import React, { useState } from 'react';
import httpClient from '../../httpClient';
import Swal from 'sweetalert2';
import { useNavigate } from 'react-router-dom';

const ResetPassword = () => {
  const [token, setToken] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!token || !newPassword) {
      Swal.fire('Error!', 'Both reset token and new password are required.', 'error');
      return;
    }
    try {
      document.body.style.cursor = 'wait';
      const response = await httpClient.put('/api/user/forgot_password', { reset_token: token, new_password: newPassword });
      if (response.status === 200) {
        Swal.fire('Success!', 'Password successfully reset.', 'success');
        //navigate('/authentication'); // Redirect to login page after reset
        navigate('/'); // Redirect to login page after reset
      } else {
        throw new Error('Error resetting password');
      }
    } catch (error) {
      Swal.fire('Error!', error.response?.data?.message || 'Failed to reset password', 'error');
    } finally {
      document.body.style.cursor = 'default';
    }
  };

  return (
    <div className="reset-password-container">
      <h2>Reset Password</h2>
      <form onSubmit={handleSubmit} className="reset-password-form">
        <div className="input-group">
          <label htmlFor="reset-token">Reset Token</label>
          <input 
            type="text"
            id="reset-token"
            value={token}
            onChange={(e) => setToken(e.target.value)}
            placeholder="Enter your reset token"
          />
        </div>
        <div className="input-group">
          <label htmlFor="new-password">New Password</label>
          <input 
            type="password"
            id="new-password"
            value={newPassword}
            onChange={(e) => setNewPassword(e.target.value)}
            placeholder="Enter your new password"
          />
        </div>
        <button type="submit" className="btn btn-primary">Reset Password</button>
      </form>
    </div>
  );
};

export default ResetPassword;
