import React, { useState, useEffect, useContext } from "react";
import SAMPLE from "../../../img/SAMPLE.jpg";
import { ReactComponent as UserLogo } from '../../../img/user_logo.svg';
import { formatDistanceToNow } from 'date-fns';
import FetchData from "../FetchFunction";
import httpClient from "../../../httpClient";
import { ThemeContext } from "../../../pages/ThemeContext";
import Swal from "sweetalert2";

const Posts = ({ privileges }) => {
  const { colorMode } = useContext(ThemeContext);
  const [activeTab, setActiveTab] = useState("posts");
  const [searchTerm, setSearchTerm] = useState("");
  const timestamp = Date.now();

  const { data: postsData, error: postsError, loading: postsLoading } = FetchData("/api/user/posts");
  const { data: announcementsData, error: announcementsError, loading: announcementsLoading } = FetchData("/api/user/announcements");

  const [myPostsData, setMyPostsData] = useState(null);
  const [myPostsLoading, setMyPostsLoading] = useState(true);
  const [myPostsError, setMyPostsError] = useState(null);
  const [canAddPost, setCanAddPost] = useState(false);

  useEffect(() => {
    setCanAddPost(privileges.add_post);
    const fetchMyPosts = async () => {
      try {
        setMyPostsLoading(true);
        const response = await httpClient.patch('/api/user/posts');
        setMyPostsData(response.data);
      } catch (error) {
        setMyPostsError(error);
      } finally {
        setMyPostsLoading(false);
      }
    };

    fetchMyPosts();
  }, []);

  let displayData = [];
  let loading = false;
  let error = null;

  if (activeTab === "posts") {
    displayData = postsData;
    loading = postsLoading;
    error = postsError;
  } else if (activeTab === "announcements") {
    displayData =
      announcementsData?.map(item => ({
        post_id: item.post.id,
        post_title: item.post.title,
        post_content: item.post.content,
        post_user_id: item.post.created_by,
        user_firstname: item.post.user.firstname,
        user_middlename: item.post.user.middlename,
        user_lastname: item.post.user.lastname,
        user_resident_type: item.post.user.resident_type,
        user_photo_path: item.post.user.photo_path,
        post_photo_path: item.post.photo_path,
        post_date_created: item.post.date_created,
        category: item.category,
        publish_date: item.publish_date
      }));
    loading = announcementsLoading;
    error = announcementsError;
  } else if (activeTab === "myPosts") {
    displayData = myPostsData;
    loading = myPostsLoading;
    error = myPostsError;
  }

  const filteredData = displayData?.filter(post =>
    post.post_title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    post.post_content.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Function to handle deletion using Swal confirmation
  const handleDeleteMyPost = async (post) => {
    console.log(post);
    const result = await Swal.fire({
      title: 'Are you sure?',
      text: "Do you want to delete this post?",
      icon: 'warning',
      showCancelButton: true,
      confirmButtonText: 'Yes, delete it!',
      cancelButtonText: 'Cancel'
    });

    if (result.isConfirmed) {
      try {
        document.body.style.cursor = 'wait';
        // Replace with your actual delete endpoint and parameter name if needed.
        await httpClient.delete('/api/user/posts', { params: { req_post_id: post.post_id } });
        Swal.fire('Deleted!', 'Your post has been deleted.', 'success');
        // Optionally, refresh the posts data.
      } catch (error) {
        Swal.fire('Error!', 'Failed to delete the post.', 'error');
      } finally {
        document.body.style.cursor = 'default';
      }
    }
  };

  // Function to handle editing using a Swal input modal
  const handleEditMyPost = async (post) => {
    const { value: formValues } = await Swal.fire({
      title: 'Edit Post',
      html: `
        <input id="swal-title" type="text" class="swal2-input" placeholder="Title" value="${post.post_title}">
        <textarea id="swal-content" class="swal2-textarea" placeholder="Content">${post.post_content}</textarea>
        <input id="swal-image" type="file" class="swal2-file">
      `,
      focusConfirm: false,
      showCancelButton: true,
      confirmButtonText: 'Update Post',
      preConfirm: () => {
        const updatedTitle = document.getElementById('swal-title').value.trim();
        const updatedContent = document.getElementById('swal-content').value.trim();
        const imageFile = document.getElementById('swal-image').files[0]; // Get file input
  
        if (!updatedTitle || !updatedContent) {
          Swal.showValidationMessage('Title and content are required');
          return false;
        }
  
        return { updatedTitle, updatedContent, imageFile };
      }
    });
  
    if (formValues) {
      const formData = new FormData();
      formData.append('req_post_id', post.post_id);
      formData.append('req_post_title', formValues.updatedTitle);
      formData.append('req_post_content', formValues.updatedContent);
  
      if (formValues.imageFile) {
        formData.append('req_post_photo', formValues.imageFile);
      }
  
      try {
        document.body.style.cursor = 'wait';
        const response = await httpClient.put('/api/user/posts', formData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
  
        if (response.status === 200) {
          Swal.fire('Success!', 'Post updated successfully.', 'success');
        } else {
          throw new Error('Error updating post');
        }
      } catch (error) {
        Swal.fire('Error!', error.response?.data?.message || 'Failed to update post', 'error');
      } finally {
        document.body.style.cursor = 'default';
      }
    }
  };
  

  if (loading) return <p>Loading posts...</p>;
  if (error) return <p>Error loading posts: {error.message}</p>;

  return (
    <div id="posts-con">
      <div>
        <div className="btn-group">
          <button onClick={() => setActiveTab("posts")} className={`btn ${activeTab === "posts" ? "btn-primary" : "btn-secondary"}`}>Posts</button>
          <button onClick={() => setActiveTab("announcements")} className={`btn ${activeTab === "announcements" ? "btn-primary" : "btn-secondary"}`}>Announcements</button>
          {privileges.add_post && (
            <button onClick={() => setActiveTab("myPosts")} className={`btn ${activeTab === "myPosts" ? "btn-primary" : "btn-secondary"}`}>My Posts</button>
          )}
        </div>
        <input
          type="text"
          placeholder="Search posts..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="p-2 border border-gray-300 rounded"
        />
        {filteredData?.length === 0 ? (
          <article className={`empty-post flex-col ${colorMode}-txt`}>
            <div className="user-metadata flex"></div>
            <div className="text-con post-metadata flex-col">
              <h5 className="post-content">No Post Available</h5>
            </div>
          </article>
        ) : (
          filteredData.map(post => (
            <article className={`flex-col post-${post.post_id} ${colorMode}-txt`} key={post.post_id}>
              <div className="user-metadata flex">
                <div className="image-con poster-image flex">
                  {!post.user_photo_path ? <UserLogo /> : (
                    <img src={`https://storage.googleapis.com/pklink/${post.user_photo_path.replace(/\\/g, "/")}`} alt={`${post.user_firstname} ${post.user_lastname}'s profile`} />
                  )}
                </div>
                <div className="text-con">
                  <h6 className="poster-name">{post.user_firstname} {post.user_lastname} <span>- {post.user_resident_type}</span></h6>
                  <p className="alt-2">{formatDistanceToNow(new Date(post.post_date_created), { addSuffix: true })} •</p>
                </div>
              </div>
              <div className="text-con post-data flex-col">
                <h6>{post.post_title}</h6>
                <h5 className="post-content">{post.post_content}</h5>
                {activeTab === "announcements" && post.category && (
                  <div className="announcement-meta">
                    <small>Category: {post.category}</small>
                  </div>
                )}
                <div className="img-con">
                  <img src={(post.post_photo_path === null || post.post_photo_path === '') ? SAMPLE : `https://storage.googleapis.com/pklink/${post.post_photo_path.replace(/\\/g, "/")}?v=${timestamp}`} alt={`Post image for ${post.post_title}`} />
                </div>
                {activeTab === "myPosts" && (
                  <div className="action-buttons flex gap-2 mt-2">
                    <button className="btn btn-secondary" onClick={() => handleEditMyPost(post)}>Edit</button>
                    <button className="btn btn-danger" onClick={() => handleDeleteMyPost(post)}>Delete</button>
                  </div>
                )}
              </div>
            </article>
          ))
        )}
      </div>
    </div>
  );
};

export default Posts;
