import Swal from "sweetalert2";
import $ from "jquery";
import "slick-carousel"; // make sure slick-carousel is installed

export function showTeamSlider() {
  Swal.fire({
    title: "Meet Our Team",
    html: `
      <div id="team-slider" style="width: 100%;">
        <!-- Slide 1: Stephen -->
        <div>
          <div class="flex-col" style="padding:20px; text-align:center; border:1px solid #ddd; border-radius:8px;">
            <img src="https://storage.googleapis.com/pklink/static/me.jpg?1" alt="Stephen" style="width:350px; height:auto; border-radius:25px; margin:0 auto 10px;">
            <h3>
                <a href="https://www.instagram.com/stephen_420__/" target="_blank">
                    Stephen Joaquin G. Aguilar
                </a>
            </h3>
            <h6>Software Developer, Designer, Cloud & Database Specialist</h6>
            <p>A valuable member of our team, driving innovation throughout the project.</p>
          </div>
        </div>
        <!-- Slide 2: Earl -->
        <div>
          <div style="padding:20px; text-align:center; border:1px solid #ddd; border-radius:8px;">
            <img src="https://storage.googleapis.com/pklink/static/ej.jpg" alt="Earl" style="width:350px; height:auto; border-radius:25px; margin:0 auto 10px;">
            <h3>
                <a href="https://www.facebook.com/rljms" target="_blank">
                    Earl James L. Dimapilis
                </a>
            </h3>
            <h6>Designer, Project Manager, and Content Curator</h6>
            <p>Ensures creative direction and oversees project workflow.</p>
          </div>
        </div>
        <!-- Slide 3: Aaron -->
        <div>
          <div style="padding:20px; text-align:center; border:1px solid #ddd; border-radius:8px;">
            <img src="https://storage.googleapis.com/pklink/static/aaron.jpg" alt="Aaron" style="width:350px; height:auto; border-radius:25px; margin:0 auto 10px;">
            <h3>
                <a href="https://www.facebook.com/kakashimoto.17" target="_blank">
                    Aaron Nathaniel N. Torres
                </a>
            </h3>
            <h6>Manuscript Editor, QA, Tester, Data Entry Specialist</h6>
            <p>Plays a crucial role in quality assurance and data management.</p>
          </div>
        </div>
      </div>
    `,
    width: 600,
    showConfirmButton: true,
    confirmButtonText: "Close",
    didOpen: () => {
      // Initialize Slick slider once the modal opens
      $('#team-slider').slick({
        dots: true,
        infinite: true,
        speed: 500,
        slidesToShow: 1,
        slidesToScroll: 1,
        autoplay: true,
      });
    },
    willClose: () => {
      // Destroy the slider instance when the modal closes to avoid conflicts on re-open
      if ($('#team-slider').hasClass('slick-initialized')) {
        $('#team-slider').slick('unslick');
      }
    }
  });
}
