import { useState, useEffect, useRef, useContext } from "react";
import Slider from "react-slick";
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";
import Swal from "sweetalert2";
import httpClient from "../../../../httpClient";
import cert_brgy from "../../../../img/cert_brgy.jpg";
import cedula from "../../../../img/cedula.jpg";
import cert_indigency from "../../../../img/cert_indigency.jpg";
import business_permit from "../../../../img/business_permit.jpg";
import { useTranslation } from 'react-i18next';
import { ThemeContext } from "../../../../pages/ThemeContext";

const CreateDocumentReqModal = ({ setRefreshRequests }) => {
    const { colorMode } = useContext(ThemeContext);
    const { t } = useTranslation();
    const [documentData, setDocumentData] = useState({
        req_document_type: "",
        req_additional_info: "",
        req_reason: "",
        req_description: "",
    });

    const [showCustomReason, setShowCustomReason] = useState(false);
    const [customReason, setCustomReason] = useState("");

    const [activeIndex, setActiveIndex] = useState(0);
    const [sliderRef, setSliderRef] = useState(null);
    const inputRef = useRef(null);
    const [searchTerm, setSearchTerm] = useState("");

    const allSlides = [
        { src: cert_brgy, label: "Barangay Certificate", value: "brgy_certificate" },
        { src: cedula, label: "Cedula", value: "cedula" },
        { src: business_permit, label: "Business Permit", value: "business_permit" },
        { src: business_permit, label: "Baranggay Clearance", value: "brgy_clearance" },
        { src: business_permit, label: "Certificate of Reesidency", value: "cert_of_residency" },
        { src: business_permit, label: "Certificate of Indigency", value: "cert_of_indigency" },
    ];

    const reasonOptions = [
        "School Purposes",
        "Job Application",
        "Bank Requirement",
        "Government Requirement",
        "Other",
    ];

    const sliderSettings = {
        centerMode: true,
        dots: true,
        speed: 500,
        slidesToShow: 3,
        slidesToScroll: 1,
        afterChange: (current) => setActiveIndex(current),
    };

    useEffect(() => {
        if (searchTerm && sliderRef) {
            const index = allSlides.findIndex(slide =>
                slide.label.toLowerCase().includes(searchTerm.toLowerCase())
            );
            if (index !== -1) {
                sliderRef.slickGoTo(index);
            }
        }
        if (inputRef.current) {
            inputRef.current.focus();
        }
    }, [searchTerm, sliderRef]);

    const handleInputChange = (e) => {
        const { name, value } = e.target;

        if (name === "req_reason") {
            setShowCustomReason(value === "Other");
            setDocumentData((prevInfo) => ({
                ...prevInfo,
                req_reason: value === "Other" ? "" : value, // Reset if "Other" is selected
            }));
        } else {
            setDocumentData((prevInfo) => ({
                ...prevInfo,
                [name]: value,
            }));
        }
    };

    const handleCustomReasonChange = (e) => {
        setCustomReason(e.target.value);
        setDocumentData((prevInfo) => ({
            ...prevInfo,
            req_reason: e.target.value, // Assign custom input value
        }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            document.body.style.cursor = "wait";
            const selectedDocument = allSlides[activeIndex]?.value;
            const dataToSend = { ...documentData, req_document_type: selectedDocument };
            const resp = await httpClient.post("/api/user/document_requests", dataToSend);

            if (resp.status === 201) {
                Swal.fire("Success!", "Your document request has been successfully submitted.", "success");
                setDocumentData({ req_document_type: "", req_additional_info: "", req_reason: "", req_description: "" });
                setCustomReason("");
                setShowCustomReason(false);
                setRefreshRequests((prev) => !prev); // Toggle state to refresh
            }
        } catch (error) {
            console.error("Error submitting document request:", error);
            Swal.fire("Error!", `${error.response.data.message}`, "error");
        } finally {
            document.body.style.cursor = "default";
        }
    };

    return (
        <div className={`document-req-create flex-col ${colorMode}-txt`}>
            <div className='text-con flex head'>
                <h4>
                    {t('content_panel.document_requests.choose_document_type')}
                </h4>
                <input 
                    ref={inputRef}
                    type="text" 
                    className={`search ${colorMode}-input`} 
                    placeholder='Search Anything' 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>

            <Slider ref={setSliderRef} {...sliderSettings}> 
                {allSlides.map((slide, index) => (
                    <div key={index} className={`document-slide ${colorMode}`} data-value={slide.value}>
                        <div className='img-con'>
                            <img src={slide.src} alt={slide.label} />
                        </div>
                        <div className='text-con'>
                            <h4>{slide.label}</h4>
                        </div>
                    </div>
                ))}
            </Slider>

            <div className='form-con'>
                <form className="document-form user-side-forms flex-col">
                    <div className="input-con flex-col">
                        <label>{t('content_panel.document_requests.reason')}</label>
                        <select 
                            name="req_reason" 
                            value={showCustomReason ? "Other" : documentData.req_reason} 
                            onChange={handleInputChange}
                        >
                            <option value="" disabled>Select a reason</option>
                            {reasonOptions.map((reason, index) => (
                                <option key={index} value={reason}>{reason}</option>
                            ))}
                        </select>

                        {/* Custom Reason Input Field */}
                        {showCustomReason && (
                            <input 
                                type="text" 
                                name="custom_reason"
                                value={customReason}
                                onChange={handleCustomReasonChange}
                                placeholder="Enter your reason"
                            />
                        )}
                    </div>

                    <div className="input-con flex-col">
                        <label>
                            {t('content_panel.document_requests.description')}
                        </label>
                        <input 
                            type="text" 
                            name="req_description" 
                            value={documentData.req_description} 
                            onChange={handleInputChange} 
                            placeholder="Enter description"
                        />
                    </div>

                    <div className="input-con flex-col">
                        <label>
                            {t('content_panel.document_requests.additional_info')}
                        </label>
                        <input 
                            type="text" 
                            name="req_additional_info" 
                            value={documentData.req_additional_info} 
                            onChange={handleInputChange} 
                            placeholder="Enter additional info"
                        />
                    </div>

                </form>
            </div>

            <button className='large' onClick={handleSubmit}>
                {t('content_panel.document_requests.proceed')}
            </button>
        </div>
    );
};

export default CreateDocumentReqModal;
