import { useTranslation } from 'react-i18next';
import Swal from 'sweetalert2';

const LanguageSwitcher = () => {
  const { i18n } = useTranslation();

  const handleChangeLanguage = async () => {
    const { value: selectedLanguage } = await Swal.fire({
      title: 'Select Language',
      input: 'select',
      inputOptions: {
        en: 'English',
        fil: 'Filipino'
      },
      inputPlaceholder: 'Choose a language',
      showCancelButton: true,
      confirmButtonText: 'Apply',
      preConfirm: (value) => {
        if (!value) {
          Swal.showValidationMessage('Please select a language');
        }
        return value;
      }
    });

    if (selectedLanguage) {
      i18n.changeLanguage(selectedLanguage);
      Swal.fire('Success', `Language changed to ${selectedLanguage.toUpperCase()}`, 'success');
    }
  };

  return (
    <button className="btn btn-info" onClick={handleChangeLanguage}>
      Change Language
    </button>
  );
};

export default LanguageSwitcher;
