import React, { useState } from 'react';
import { useNavigate  } from 'react-router-dom';
import httpClient from '../../httpClient';
import Swal from 'sweetalert2';
function Login() {
  
    const [data, setData]= useState({
        req_user_username: '',
        req_user_password: ''
    }); 
    const navigate = useNavigate();

    const handleChange = (e) => {
      const { name, value } = e.target;
      setData({ ...data, [name]: value });
    };

    const handleSubmit = async(e) => {
      e.preventDefault();
      if (!data.req_user_username || !data.req_user_password){
        return;
      } 
      logInUser();
    };

    const handleForgotPassword = async () => {
      const { value: formValues } = await Swal.fire({
        title: 'Forgot Password',
        html: `
          <input id="swal-username-f" type="text" class="swal2-input" placeholder="Username">
          <input id="swal-email-f" type="email" class="swal2-input" placeholder="Registered Email">
          <input id="swal-lastname-f" type="text" class="swal2-input" placeholder="Last Name">
        `,
        focusConfirm: false,
        showCancelButton: true,
        confirmButtonText: 'Reset Password',
        preConfirm: () => {
          const req_user_username = document.getElementById('swal-username-f').value.trim();
          const req_user_email = document.getElementById('swal-email-f').value.trim();
          const req_user_lastname = document.getElementById('swal-lastname-f').value.trim();
          if (!req_user_username || !req_user_email || !req_user_lastname) {
            Swal.showValidationMessage('All fields are required');
            return false;
          }
          return { req_user_username, req_user_email, req_user_lastname };
        }
      });
    
      if (formValues) {
        try {
          document.body.style.cursor = 'wait';
          const response = await httpClient.post('/api/user/forgot_password', formValues);
          if (response.status === 200) {
            Swal.fire('Success!', 'Password reset instructions sent to your email.', 'success');
          } else {
            throw new Error('Error processing request');
          }
        } catch (error) {
          Swal.fire('Error!', error.response?.data?.message || 'Failed to send reset email', 'error');
        } finally {
          document.body.style.cursor = 'default';
        }
      }
    };
    
  

    const logInUser = async() => {

      try {
        document.body.style.cursor = 'wait';
        const resp = await httpClient.post('/api/user/auth', data);

        if (resp.status !== 200) {
          Swal.fire('Failed!', 'Login Failed.', 'failed');
          return;
        }
        navigate('/user/dashboard');
        Swal.fire({
          title: "Login Complete!",
          html: "Redirecting to dashboard",
          timer: 1000,
          timerProgressBar: true
        });
      } catch (error) {
        if (error.status===406){
          Swal.fire('Failed!', 'Wrong credentials', 'failed');
          return;
        }
        else if (error.status===410){
          Swal.fire('Failed!', 'Wrong credentials', 'failed');
          return;
        }
        Swal.fire('Error!', 'Internal server error', 'error');
        return;
      } finally {
        document.body.style.cursor = 'default';
      }
    };
    return (
      <>
        <form onSubmit={handleSubmit} className='flex-col'>
          <div className='input-con flex-col'>
            <label for="req_user_username">Username</label>
            <input 
              type="text"
              name="req_user_username" 
              placeholder="username"
              value={data.req_user_username}
              onChange={handleChange}
            />
          </div>
          <div className='input-con flex-col'>
            <label for="req_user_username">Password</label>
            <input
              type="password" 
              name="req_user_password" 
              placeholder="password"
              value={data.req_user_password}
              onChange={handleChange}
            />  
          </div>
          <div className='text-con'>
            <a
             href=""
             onClick={(e) => { e.preventDefault(); handleForgotPassword(); }}
            >Forgot password?</a>
          </div>
          <button 
            className='button'
            type='submit'>
            Sign In
          </button>
        </form>
      </>
      
    );
  }
  
  export default Login;
  