import { useState, useEffect } from "react";
import { Bar, Pie, Doughnut, Line, Radar, PolarArea } from "react-chartjs-2";
import { Chart as ChartJS, CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend, ArcElement, PointElement, LineElement, RadialLinearScale } from "chart.js";
import httpClient from "../../../httpClient";

// Register all needed Chart.js components
ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend, ArcElement, PointElement, LineElement, RadialLinearScale);

const chartTypes = {
    bar: Bar,
    horizontalBar: Bar,
    pie: Pie,
    doughnut: Doughnut,
    line: Line,
    radar: Radar,
    polarArea: PolarArea,
};

const HealthSupportRequestsChart = () => {
    const [chartData, setChartData] = useState({ labels: [], datasets: [] });
    const [selectedChart, setSelectedChart] = useState("bar"); // Default to bar chart

    useEffect(() => {
        httpClient.get(`/api/admin/health-support-requests-stats`)
            .then((response) => {
                const { labels, data } = response.data.data || {};

                if (!labels || !data) {
                    console.warn("Invalid data structure received for document requests.");
                    return;
                }

                setChartData({
                    labels,
                    datasets: [
                        {
                            label: "Health Support Requests",
                            data,
                            backgroundColor: ["#ff6384", "#36a2eb"],
                        },
                    ],
                });
            })
            .catch((error) => {
                console.error("Error fetching health support requests statistics:", error);
            });
    }, []);

    const ChartComponent = chartTypes[selectedChart];

    return (
        <div className="p-4">
            {/* Dropdown for selecting chart type */}
            <div className="mb-4">
                <label className="font-medium mr-2">Select Chart Type:</label>
                <select
                    className="p-2 border rounded"
                    value={selectedChart}
                    onChange={(e) => setSelectedChart(e.target.value)}
                >
                    <option value="bar">Bar Chart</option>
                    <option value="horizontalBar">Horizontal Bar Chart</option>
                    <option value="pie">Pie Chart</option>
                    <option value="doughnut">Doughnut Chart</option>
                    <option value="line">Line Chart</option>
                    <option value="radar">Radar Chart</option>
                    <option value="polarArea">Polar Area Chart</option>
                </select>
            </div>

            {/* Chart Display */}
            <div className="w-full h-[400px]">
                {ChartComponent && <ChartComponent data={chartData} options={{ responsive: true, maintainAspectRatio: false, indexAxis: selectedChart === "horizontalBar" ? "y" : "x" }} />}
            </div>
        </div>
    );
};

export default HealthSupportRequestsChart;
