import Swal from "sweetalert2";
import { useState, useContext } from "react";
import httpClient from "../../../../httpClient";
import { useTranslation } from 'react-i18next';
import { ThemeContext } from "../../../../pages/ThemeContext";

const CreateIncidentModal = () => {
    const { colorMode } = useContext(ThemeContext);
    const { t } = useTranslation();
    
    const [incidentData, setIncidentData] = useState({
        description: '',
        customDescription: '',
        location: '',
        photo: null,
    });

    const [showCustomInput, setShowCustomInput] = useState(false);

    const incidentOptions = [
        'Fight',
        'Vehicular Accident',
        'Electricity Outbreak',
        'Fire',
        'Robbery',
        'Medical Emergency',
        'Vandalism',
        'Other',
    ];

    const handleInputChange = (e) => {
        const { name, value } = e.target;

        if (name === "description") {
            setShowCustomInput(value === "Other");
            setIncidentData((prev) => ({
                ...prev,
                description: value,
                customDescription: value === "Other" ? "" : prev.customDescription,
            }));
        } else {
            setIncidentData((prev) => ({
                ...prev,
                [name]: value,
            }));
        }
    };

    const handleFileChange = (e) => {
        setIncidentData((prev) => ({
            ...prev,
            photo: e.target.files[0],
        }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        const formData = new FormData();
        formData.append('req_description', showCustomInput ? incidentData.customDescription : incidentData.description);
        formData.append('req_location', incidentData.location);
        formData.append('req_incident_photo', incidentData.photo);

        try {
            document.body.style.cursor = 'wait';
            const response = await httpClient.post('/api/user/incidents', formData, {
                headers: { 'Content-Type': 'multipart/form-data' },
            });

            if (response.status === 200) {
                Swal.fire({
                    icon: 'success',
                    title: 'Incident Reported',
                    text: 'Your incident has been successfully reported.',
                });

                // Reset form
                setIncidentData({
                    description: '',
                    customDescription: '',
                    location: '',
                    photo: null,
                });
                setShowCustomInput(false);
            } else {
                throw new Error('Something went wrong!');
            }
        } catch (error) {
            console.log(error);
            Swal.fire({
                icon: 'error',
                title: 'Error!',
                text: `${error.response?.data.message}`,
            });
        } finally {
            document.body.style.cursor = 'default';
        }
    };

    return (
        <div className={`incident-create flex-col ${colorMode}-txt`}>
            <div className="text-con head">
                {t('content_panel.incident.report_incident')}
            </div>
            <div className="form-con">
                <form className="user-side-forms flex-col" onSubmit={handleSubmit}>
                    <div className="input-con flex-col">
                        <label>{t('content_panel.incident.description')}</label>
                        <select name="description" value={incidentData.description} onChange={handleInputChange}>
                            <option value="" disabled>Select an incident type</option>
                            {incidentOptions.map((option, index) => (
                                <option key={index} value={option}>{option}</option>
                            ))}
                        </select>
                        {showCustomInput && (
                            <input 
                                type="text" 
                                name="customDescription" 
                                value={incidentData.customDescription} 
                                onChange={handleInputChange} 
                                placeholder="Enter custom description"
                            />
                        )}
                    </div>
                    <div className="input-con flex-col">
                        <label>{t('content_panel.incident.location')}</label>
                        <input
                            type="text"
                            placeholder="Enter your answer here"
                            name="location"
                            value={incidentData.location}
                            onChange={handleInputChange}
                        />
                    </div>
                    <div className="input-con flex-col">
                        <label>{t('content_panel.incident.photo')}</label>
                        <input
                            type="file"
                            name="req_incident_photo"
                            onChange={handleFileChange}
                        />
                    </div>
                    <button type="submit">{t('content_panel.incident.proceed')}</button>
                </form>
            </div>
        </div>
    );
};

export default CreateIncidentModal;
