import { useState, useEffect } from "react";
import { Bar, Line, Pie } from "react-chartjs-2";
import { Chart as ChartJS, CategoryScale, LinearScale, BarElement, LineElement, PointElement, ArcElement, Title, Tooltip, Legend } from "chart.js";
import httpClient from "../../../httpClient";

ChartJS.register(CategoryScale, LinearScale, BarElement, LineElement, PointElement, ArcElement, Title, Tooltip, Legend);

const UsersByResidentTypeChart = () => {
    const [chartData, setChartData] = useState({ labels: [], datasets: [] });
    const [chartType, setChartType] = useState("bar");

    useEffect(() => {
        httpClient.get("/api/admin/residenttype-stats")
            .then((response) => {
                const data = response.data.data || response.data;
                if (!data.labels.length || !data.counts.length) {
                    console.warn("No data available for resident type statistics.");
                    return;
                }
                
                // Create a unique color for each label using HSL
                const colors = data.labels.map((_, idx) => {
                    const hue = (idx * 360) / data.labels.length;
                    return `hsl(${hue}, 70%, 60%)`;
                });

                setChartData({
                    labels: data.labels,
                    datasets: [{
                        label: "Users by Resident Type",
                        data: data.counts,
                        backgroundColor: colors,
                    }],
                });
            })
            .catch((error) => {
                console.error("Error fetching users by resident type:", error);
            });
    }, []);

    const renderChart = () => {
        switch (chartType) {
            case "line":
                return <Line data={chartData} options={{ responsive: true, maintainAspectRatio: false }} />;
            case "pie":
                return <Pie data={chartData} options={{ responsive: true, maintainAspectRatio: false }} />;
            default:
                return <Bar data={chartData} options={{ responsive: true, maintainAspectRatio: false }} />;
        }
    };

    return (
        <div className="p-4">
            <div className="mb-4">
                <label className="mr-2">Chart Type:</label>
                <select
                    value={chartType}
                    onChange={(e) => setChartType(e.target.value)}
                    className="p-2 border rounded"
                >
                    <option value="bar">Bar Chart</option>
                    <option value="line">Line Chart</option>
                    <option value="pie">Pie Chart</option>
                </select>
            </div>
            <div className="w-full h-[1000px] overflow-hidden">
                {renderChart()}
            </div>
        </div>
    );
};

export default UsersByResidentTypeChart;
