import { useState } from "react";
import UserRegistrationChart from "../charts/UserRegistrationChart";
import UsersByResidentTypeChart from "../charts/UsersByResidentTypeChart";
import RequestsStatisticsChart from "../charts/RequestStatisticsChart";
import DocumentRequestsChart from "../charts/DocumentRequestsChart";
import HealthSupportRequestsChart from "../charts/HealthSupportRequestsChart";

function ChartDashboard() {
    const [activeView, setActiveView] = useState("user_registration");

    const renderCharts = () => {
        switch (activeView) {
            case "user_registration":
                return (
                    <UserRegistrationChart />
                );
            case "users_by_resident_type":
                return (
                    <UsersByResidentTypeChart />
                );
            case "request_statistics":
                return (
                    <RequestsStatisticsChart />
                );
            case "document_request_statistics":
                return (
                    <DocumentRequestsChart />
                );
            case "health_support_request_statistics":
                return (
                    <HealthSupportRequestsChart />
                );
            default:
                return <p>Select a view to display charts</p>;
        }
    };

    return (
        <div id="chart-dashboard-con" className="p-4">
            <div>
                <h2 className="text-xl font-bold mb-4">Data Visualization Dashboard</h2>
                
                <div className="mb-4">
                    <label className="block text-sm font-medium text-gray-700 mb-1">Select a View:</label>
                    <select
                        className="w-full p-2 border border-gray-300 rounded-lg"
                        value={activeView}
                        onChange={(e) => setActiveView(e.target.value)}
                    >
                        <option value="user_registration">User Registraion Chart</option>
                        <option value="users_by_resident_type">Users by Resident Type Chart</option>
                        <option value="request_statistics">Request Statistics Chart</option>
                        <option value="document_request_statistics">Document Request Statistics Chart</option>
                        <option value="health_support_request_statistics">Health Support Request Statistics Chart</option>
                    </select>
                </div>

                <div className="bg-white p-4 shadow rounded-lg grid grid-cols-1 md:grid-cols-2 gap-4">
                    {renderCharts()}
                </div>
            </div>
        </div>
    );
}

export default ChartDashboard;
