import Swal from "sweetalert2";

// Function to show Terms and Conditions modal
export function showTermsModal() {
  Swal.fire({
    title: "Terms and Conditions",
    html: `
      <div style="text-align: left; max-height: 300px; overflow-y: auto; padding: 10px;">
        <p>Please read our terms before proceeding:</p>
        <ul>
          <li>We respect your privacy and handle your data responsibly.</li>
          <li>By using our services, you agree to our terms and policies.</li>
          <li>We reserve the right to update these terms at any time.</li>
        </ul>
        <p>Click "Accept" to continue.</p>
      </div>
    `,
    icon: "info",
    allowOutsideClick: false,
    showCancelButton: false,
    confirmButtonText: "Accept",
  }).then((result) => {
    if (result.isConfirmed) {
      // Save acceptance in session storage (or any other state management)
      sessionStorage.setItem("acceptedTerms", "true");
    }
  });
}
