import { useContext } from 'react';
import { ThemeContext } from '../../pages/ThemeContext'; // adjust the path as needed
import { showTermsModal } from './TermsAndConditions';
import { showPrivacyPolicy } from './showPrivacyPolicy';
import { showFigmaSitemap } from './showFigmaSitemap';
import { showTeamSlider } from './showTeamSlider';

function Footer() {
    const { colorMode } = useContext(ThemeContext);
    return (
        <footer id="footer" className={`${colorMode}-gray-bg ${colorMode}-txt user-auth`}>
            <div className="flex">
                <div className="left flex">
                    <p className="alt-2">Copyright 2025. All Rights Reserved. &copy;</p>
                    <ul className="flex">
                        <li>
                            <a href="#">
                                <p className="alt-2" onClick={() => showPrivacyPolicy()} >Privacy</p>
                            </a>
                        </li>
                        <li>
                            <a href="#" onClick={() => showTermsModal()}>
                                <p className="alt-2">Terms</p>
                            </a>
                        </li>
                        <li>
                            <a href="#" onClick={() => showFigmaSitemap()}>
                                <p className="alt-2">Sitemap</p>
                            </a>
                        </li>
                        <li>
                            <a href="#" onClick={() => showTeamSlider()}>
                                <p className="alt-2">Team</p>
                            </a>
                        </li>
                    </ul>
                </div>
                <div className="right flex">
                    <div className="text-con flex">
                        <i className="bi bi-facebook"></i>
                        <p className="alt-2">
                            <a href="https://www.facebook.com/profile.php?id=61570338221503" target='_blank'>
                                Pamahalaang Barangay ng Puting Kahoy
                            </a>
                        </p>
                    </div>
                    <div className="text-con flex">
                        <i className="bi bi-telephone"></i>
                        <p className="alt-2">
                            <a href="tel:+631234567890" className="alt-2">+63 123 456 7890</a>
                        </p>
                    </div>
                </div>
            </div>
        </footer>
    );
}

export default Footer;
